  ControlAuthority.Input input(long seq,long at){return new ControlAuthority.Input(cfg.context,SOURCE,"ANDROID_UPTIME_NS_SAMPLER","ROOT_INJECTED_ANDROID_TOUCH",seq,at,at,0,new double[4],0,-1,false);}
