  public OutputStream output(){return new OutputStream(){public void write(int b){}public void write(byte[]b,int o,int n)throws IOException{try{writes++;if(writes==7){ControlSession s=session(owner[0]);s.observeLoop(time.get());auth(owner[0]).accept(input(1,time.get()),time.get());auth(owner[0]).consent(time.get(),"EXPLICIT_TEST_CONSENT");owner[0].input(fault.equals("null-input")?null:input(2,1050000000L));time.set(1090000000L);seeded=true;}if(writes==8&&fault.equals("midloop")){time.set(1240000000L);owner[0].input(input(3,1150000000L));}stall("socket.write");}catch(Exception e){throw new IOException(e);}}public void flush()throws IOException{try{stall("socket.flush");}catch(Exception e){throw new IOException(e);}}};}
