   owner[0]=new ControlOwner(files,cfg,clock,sync,()->true,(id,value)->state=value,SOURCE,()->this);owner[0].start();Field f=ControlOwner.class.getDeclaredField("thread");f.setAccessible(true);Thread thread=(Thread)f.get(owner[0]);thread.join(5000);check(!thread.isAlive()&&closed,"boundedFDclosure");
